mapper.select:
SELECT m.device_id AS deviceId, m.device_code AS deviceCode, d.device_name AS deviceName, m.point_code AS pointCode, p.property_name AS pointName, m.unit AS unit, m.data_time AS dataTime, m.point_value AS value, m.quality AS quality FROM iot_telemetry_minute m LEFT JOIN iot_device d ON m.device_id = d.id AND d.deleted = 0 LEFT JOIN iot_device_point p ON m.device_id = p.device_id AND m.point_code = p.property_code AND p.deleted = 0
ORDER BY m.device_id, m.point_code, m.minute_time
LIMIT #{req.limit}
OFFSET #{req.offset}

SELECT x.device_id AS deviceId, x.device_code AS deviceCode, d.device_name AS deviceName, x.point_code AS pointCode, p.property_name AS pointName, x.unit AS unit, x.quality AS quality, MIN(x.point_value) AS minValue, MAX(x.point_value) AS maxValue, AVG(x.point_value) AS avgValue, SUM(x.point_value) AS sumValue, COUNT(1) AS count, x.bucket_start AS startTime,
DATE_SUB(DATE_ADD(x.bucket_start, INTERVAL 1 DAY), INTERVAL 1 SECOND) AS endTime
DATE_SUB(DATE_ADD(x.bucket_start, INTERVAL 1 HOUR), INTERVAL 1 SECOND) AS endTime
FROM ( SELECT m.*,
STR_TO_DATE(DATE_FORMAT(m.minute_time, '%Y-%m-%d 00:00:00'), '%Y-%m-%d %H:%i:%s')
STR_TO_DATE(DATE_FORMAT(m.minute_time, '%Y-%m-%d %H:00:00'), '%Y-%m-%d %H:%i:%s')
AS bucket_start FROM iot_telemetry_minute m
) x LEFT JOIN iot_device d ON x.device_id = d.id AND d.deleted = 0 LEFT JOIN iot_device_point p ON x.device_id = p.device_id AND x.point_code = p.property_code AND p.deleted = 0 GROUP BY x.device_id, x.device_code, d.device_name, x.point_code, p.property_name, x.unit, x.quality, x.bucket_start ORDER BY x.device_id, x.point_code, x.bucket_start
LIMIT #{req.limit}
OFFSET #{req.offset}

SELECT
  r.source_code AS sourceCode,
  r.device_id AS deviceId,
  r.external_device_id AS externalDeviceId,
  r.external_metric AS externalMetric,
  r.data_time AS dataTime,
  r.raw_value AS rawValue,
  r.receive_time AS receiveTime,
  r.raw_payload AS rawPayload,
  r.match_status AS matchStatus,
  r.create_time AS createTime
FROM iot_telemetry_raw r


    AND 1 = 0


    AND r.ent_id = #{req.entId}



      AND r.ent_id IN (
        SELECT e.ent_id
        FROM aggregator_ent e
        WHERE e.aggregator_id = #{req.aggregatorId}
      )



    AND r.device_id = #{req.deviceId}


    AND r.device_id IN

      #{id}



    AND r.external_device_id LIKE CONCAT('%', #{req.externalDeviceId}, '%')


    AND r.external_metric LIKE CONCAT('%', #{req.externalMetric}, '%')


    AND r.match_status = #{req.matchStatus}


    AND r.data_time >= #{req.startTime}


    AND r.data_time <= #{req.endTime}


ORDER BY r.data_time DESC

  LIMIT #{req.limit}


  OFFSET #{req.offset}

SELECT COUNT(1)
FROM iot_telemetry_raw r


    AND 1 = 0


    AND r.ent_id = #{req.entId}



      AND r.ent_id IN (
        SELECT e.ent_id
        FROM aggregator_ent e
        WHERE e.aggregator_id = #{req.aggregatorId}
      )



    AND r.device_id = #{req.deviceId}


    AND r.device_id IN

      #{id}



    AND r.external_device_id LIKE CONCAT('%', #{req.externalDeviceId}, '%')


    AND r.external_metric LIKE CONCAT('%', #{req.externalMetric}, '%')


    AND r.match_status = #{req.matchStatus}


    AND r.data_time >= #{req.startTime}


    AND r.data_time <= #{req.endTime}

SELECT t.device_id AS deviceId, t.device_code AS deviceCode, d.device_name AS deviceName, t.ent_id AS entId, t.point_code AS pointCode, p.property_name AS pointName, t.unit AS unit, t.point_value AS currentValue, t.minute_time AS currentTime, t.quality AS quality, t2.point_value AS prevValue, t2.minute_time AS prevTime, (t.point_value - t2.point_value) AS delta, CASE WHEN t.point_value > t2.point_value THEN 'up' WHEN t.point_value < t2.point_value THEN 'down' ELSE 'stable' END AS trend FROM iot_telemetry_minute t LEFT JOIN iot_device d ON t.device_id = d.id AND d.deleted = 0 LEFT JOIN iot_device_point p ON t.device_id = p.device_id AND t.point_code = p.property_code AND p.deleted = 0 LEFT JOIN iot_telemetry_minute t2 ON t2.device_id = t.device_id AND t2.point_code = t.point_code AND t2.minute_time = ( SELECT MAX(t3.minute_time) FROM iot_telemetry_minute t3 WHERE t3.device_id = t.device_id AND t3.point_code = t.point_code AND t3.minute_time < t.minute_time
AND t3.aggregator_id = #{req.aggregatorId}
AND t3.ent_id = #{req.entId}
) WHERE t.minute_time = ( SELECT MAX(t4.minute_time) FROM iot_telemetry_minute t4 WHERE t4.device_id = t.device_id AND t4.point_code = t.point_code
AND t4.aggregator_id = #{req.aggregatorId}
AND t4.ent_id = #{req.entId}
)
AND 1 = 0
AND t.aggregator_id = #{req.aggregatorId}
AND t.ent_id = #{req.entId}
AND t.device_id IN
#{id}
AND t.point_code IN
#{code}
ORDER BY t.device_id, t.point_code
LIMIT #{req.limit}
